-- Lot 001 : les 12 categories V3, leur categorie de transition, et les 71
-- collections.
--
-- Les references sont prefixees (V3- / V3C-) : une categorie V3 ne
-- doit jamais ecraser une V2 qui porterait le meme slug. Les anciennes
-- restent en place tant qu'elles portent des cartes — c'est le lot 900 qui
-- les vide, apres controle.

begin;

drop table if exists lot_cat_v3;
create temporary table lot_cat_v3 as
select * from jsonb_to_recordset($raccourcia$[{"ref":"V3-portrait-identite","slug":"portrait-identite","nom":"Portrait & identité","ordre":1},{"ref":"V3-retouche-restauration","slug":"retouche-restauration","nom":"Retouche & restauration","ordre":2},{"ref":"V3-photomontage-effets","slug":"photomontage-effets","nom":"Photomontage & effets","ordre":3},{"ref":"V3-produit-ecommerce","slug":"produit-ecommerce","nom":"Produit & e-commerce","ordre":4},{"ref":"V3-marque-publicite","slug":"marque-publicite","nom":"Marque & publicité","ordre":5},{"ref":"V3-design-edition","slug":"design-edition","nom":"Design graphique & édition","ordre":6},{"ref":"V3-illustration-arts","slug":"illustration-arts","nom":"Illustration & arts","ordre":7},{"ref":"V3-espaces-architecture","slug":"espaces-architecture","nom":"Espaces & architecture","ordre":8},{"ref":"V3-information-visualisation","slug":"information-visualisation","nom":"Information & visualisation","ordre":9},{"ref":"V3-evenements-souvenirs","slug":"evenements-souvenirs","nom":"Événements & souvenirs","ordre":10},{"ref":"V3-fiction-divertissement","slug":"fiction-divertissement","nom":"Fiction & divertissement","ordre":11},{"ref":"V3-voyages-cultures-epoques","slug":"voyages-cultures-epoques","nom":"Voyages, cultures & époques","ordre":12},{"ref":"V3-a-reclasser","slug":"a-reclasser","nom":"À reclasser","ordre":99,"description":"Commandes du catalogue précédent qui attendent leur catégorie V3. Elles fonctionnent normalement."}]$raccourcia$)
as x(ref text, slug text, nom text, ordre integer, description text);

insert into public.categories (external_ref, slug, name, mode, sort_order, short_description, status, is_visible)
select l.ref, l.slug, l.nom, 'image'::public.app_mode, l.ordre, l.description,
       'published'::public.content_status, true
from lot_cat_v3 l
on conflict (external_ref) where external_ref is not null do update
set name = excluded.name,
    sort_order = excluded.sort_order,
    short_description = coalesce(excluded.short_description, public.categories.short_description),
    is_visible = true;

drop table if exists lot_col_v3;
create temporary table lot_col_v3 as
select * from jsonb_to_recordset($raccourcia$[{"ref":"V3C-design-edition--creation-decorative","slug":"design-edition--creation-decorative","nom":"Création décorative","parent":"V3-design-edition"},{"ref":"V3C-design-edition--ecrans-et-interfaces","slug":"design-edition--ecrans-et-interfaces","nom":"Écrans et interfaces","parent":"V3-design-edition"},{"ref":"V3C-design-edition--evenements-et-spectacles","slug":"design-edition--evenements-et-spectacles","nom":"Événements et spectacles","parent":"V3-design-edition"},{"ref":"V3C-design-edition--fetes-et-calendrier","slug":"design-edition--fetes-et-calendrier","nom":"Fêtes et calendrier","parent":"V3-design-edition"},{"ref":"V3C-design-edition--graphisme-contemporain","slug":"design-edition--graphisme-contemporain","nom":"Graphisme contemporain","parent":"V3-design-edition"},{"ref":"V3C-design-edition--livres-et-divertissement","slug":"design-edition--livres-et-divertissement","nom":"Livres et divertissement","parent":"V3-design-edition"},{"ref":"V3C-design-edition--objets-et-metamorphoses","slug":"design-edition--objets-et-metamorphoses","nom":"Objets et métamorphoses","parent":"V3-design-edition"},{"ref":"V3C-design-edition--portrait-et-editorial","slug":"design-edition--portrait-et-editorial","nom":"Portrait et éditorial","parent":"V3-design-edition"},{"ref":"V3C-design-edition--presse-et-magazines","slug":"design-edition--presse-et-magazines","nom":"Presse et magazines","parent":"V3-design-edition"},{"ref":"V3C-design-edition--supports-et-formats","slug":"design-edition--supports-et-formats","nom":"Supports et formats","parent":"V3-design-edition"},{"ref":"V3C-design-edition--univers-personnels","slug":"design-edition--univers-personnels","nom":"Univers personnels","parent":"V3-design-edition"},{"ref":"V3C-espaces-architecture--architecture-et-urbanisme","slug":"espaces-architecture--architecture-et-urbanisme","nom":"Architecture et urbanisme","parent":"V3-espaces-architecture"},{"ref":"V3C-espaces-architecture--espaces-professionnels","slug":"espaces-architecture--espaces-professionnels","nom":"Espaces professionnels","parent":"V3-espaces-architecture"},{"ref":"V3C-espaces-architecture--habitat-et-exterieur","slug":"espaces-architecture--habitat-et-exterieur","nom":"Habitat et extérieur","parent":"V3-espaces-architecture"},{"ref":"V3C-espaces-architecture--volumes-et-amenagements","slug":"espaces-architecture--volumes-et-amenagements","nom":"Volumes et aménagements","parent":"V3-espaces-architecture"},{"ref":"V3C-evenements-souvenirs--etapes-de-vie","slug":"evenements-souvenirs--etapes-de-vie","nom":"Étapes de vie","parent":"V3-evenements-souvenirs"},{"ref":"V3C-evenements-souvenirs--fetes-et-calendrier","slug":"evenements-souvenirs--fetes-et-calendrier","nom":"Fêtes et calendrier","parent":"V3-evenements-souvenirs"},{"ref":"V3C-evenements-souvenirs--moments-et-celebrations","slug":"evenements-souvenirs--moments-et-celebrations","nom":"Moments et célébrations","parent":"V3-evenements-souvenirs"},{"ref":"V3C-evenements-souvenirs--union-et-famille","slug":"evenements-souvenirs--union-et-famille","nom":"Union et famille","parent":"V3-evenements-souvenirs"},{"ref":"V3C-fiction-divertissement--animation-et-creatures","slug":"fiction-divertissement--animation-et-creatures","nom":"Animation et créatures","parent":"V3-fiction-divertissement"},{"ref":"V3C-fiction-divertissement--cinema-et-pop-culture","slug":"fiction-divertissement--cinema-et-pop-culture","nom":"Cinéma et pop culture","parent":"V3-fiction-divertissement"},{"ref":"V3C-fiction-divertissement--fantasy-et-uchronies","slug":"fiction-divertissement--fantasy-et-uchronies","nom":"Fantasy et uchronies","parent":"V3-fiction-divertissement"},{"ref":"V3C-fiction-divertissement--objets-et-metamorphoses","slug":"fiction-divertissement--objets-et-metamorphoses","nom":"Objets et métamorphoses","parent":"V3-fiction-divertissement"},{"ref":"V3C-fiction-divertissement--scenes-et-detournements","slug":"fiction-divertissement--scenes-et-detournements","nom":"Scènes et détournements","parent":"V3-fiction-divertissement"},{"ref":"V3C-fiction-divertissement--univers-et-personnages","slug":"fiction-divertissement--univers-et-personnages","nom":"Univers et personnages","parent":"V3-fiction-divertissement"},{"ref":"V3C-illustration-arts--dessin-et-ecriture","slug":"illustration-arts--dessin-et-ecriture","nom":"Dessin et écriture","parent":"V3-illustration-arts"},{"ref":"V3C-illustration-arts--graphisme-contemporain","slug":"illustration-arts--graphisme-contemporain","nom":"Graphisme contemporain","parent":"V3-illustration-arts"},{"ref":"V3C-illustration-arts--laboratoire-visuel","slug":"illustration-arts--laboratoire-visuel","nom":"Laboratoire visuel","parent":"V3-illustration-arts"},{"ref":"V3C-illustration-arts--matieres-et-patrimoine","slug":"illustration-arts--matieres-et-patrimoine","nom":"Matières et patrimoine","parent":"V3-illustration-arts"},{"ref":"V3C-illustration-arts--mediums-et-explorations","slug":"illustration-arts--mediums-et-explorations","nom":"Médiums et explorations","parent":"V3-illustration-arts"},{"ref":"V3C-illustration-arts--narration-dessinee","slug":"illustration-arts--narration-dessinee","nom":"Narration dessinée","parent":"V3-illustration-arts"},{"ref":"V3C-illustration-arts--peinture-et-grands-maitres","slug":"illustration-arts--peinture-et-grands-maitres","nom":"Peinture et grands maîtres","parent":"V3-illustration-arts"},{"ref":"V3C-information-visualisation--comprendre-et-comparer","slug":"information-visualisation--comprendre-et-comparer","nom":"Comprendre et comparer","parent":"V3-information-visualisation"},{"ref":"V3C-information-visualisation--comprendre-et-representer","slug":"information-visualisation--comprendre-et-representer","nom":"Comprendre et représenter","parent":"V3-information-visualisation"},{"ref":"V3C-information-visualisation--matieres-et-metamorphoses","slug":"information-visualisation--matieres-et-metamorphoses","nom":"Matières et métamorphoses","parent":"V3-information-visualisation"},{"ref":"V3C-information-visualisation--plans-et-documentation","slug":"information-visualisation--plans-et-documentation","nom":"Plans et documentation","parent":"V3-information-visualisation"},{"ref":"V3C-information-visualisation--presentation-produit","slug":"information-visualisation--presentation-produit","nom":"Présentation produit","parent":"V3-information-visualisation"},{"ref":"V3C-information-visualisation--sciences-et-technique","slug":"information-visualisation--sciences-et-technique","nom":"Sciences et technique","parent":"V3-information-visualisation"},{"ref":"V3C-marque-publicite--campagnes-et-acquisition","slug":"marque-publicite--campagnes-et-acquisition","nom":"Campagnes et acquisition","parent":"V3-marque-publicite"},{"ref":"V3C-marque-publicite--fetes-et-calendrier","slug":"marque-publicite--fetes-et-calendrier","nom":"Fêtes et calendrier","parent":"V3-marque-publicite"},{"ref":"V3C-marque-publicite--identite-et-campagnes","slug":"marque-publicite--identite-et-campagnes","nom":"Identité et campagnes","parent":"V3-marque-publicite"},{"ref":"V3C-marque-publicite--identite-et-direction-artistique","slug":"marque-publicite--identite-et-direction-artistique","nom":"Identité et direction artistique","parent":"V3-marque-publicite"},{"ref":"V3C-photomontage-effets--compositing-et-decors","slug":"photomontage-effets--compositing-et-decors","nom":"Compositing et décors","parent":"V3-photomontage-effets"},{"ref":"V3C-photomontage-effets--lumiere-et-optique","slug":"photomontage-effets--lumiere-et-optique","nom":"Lumière et optique","parent":"V3-photomontage-effets"},{"ref":"V3C-photomontage-effets--matieres-et-metamorphoses","slug":"photomontage-effets--matieres-et-metamorphoses","nom":"Matières et métamorphoses","parent":"V3-photomontage-effets"},{"ref":"V3C-photomontage-effets--montages-et-illusions","slug":"photomontage-effets--montages-et-illusions","nom":"Montages et illusions","parent":"V3-photomontage-effets"},{"ref":"V3C-photomontage-effets--temps-et-mouvement","slug":"photomontage-effets--temps-et-mouvement","nom":"Temps et mouvement","parent":"V3-photomontage-effets"},{"ref":"V3C-portrait-identite--beaute-et-coiffure","slug":"portrait-identite--beaute-et-coiffure","nom":"Beauté et coiffure","parent":"V3-portrait-identite"},{"ref":"V3C-portrait-identite--liens-et-souvenirs","slug":"portrait-identite--liens-et-souvenirs","nom":"Liens et souvenirs","parent":"V3-portrait-identite"},{"ref":"V3C-portrait-identite--portrait-et-editorial","slug":"portrait-identite--portrait-et-editorial","nom":"Portrait et éditorial","parent":"V3-portrait-identite"},{"ref":"V3C-portrait-identite--portraits-et-presence-sociale","slug":"portrait-identite--portraits-et-presence-sociale","nom":"Portraits et présence sociale","parent":"V3-portrait-identite"},{"ref":"V3C-portrait-identite--style-et-essayage","slug":"portrait-identite--style-et-essayage","nom":"Style et essayage","parent":"V3-portrait-identite"},{"ref":"V3C-portrait-identite--transformation-et-identite","slug":"portrait-identite--transformation-et-identite","nom":"Transformation et identité","parent":"V3-portrait-identite"},{"ref":"V3C-produit-ecommerce--presentation-et-mise-en-scene","slug":"produit-ecommerce--presentation-et-mise-en-scene","nom":"Présentation et mise en scène","parent":"V3-produit-ecommerce"},{"ref":"V3C-produit-ecommerce--presentation-produit","slug":"produit-ecommerce--presentation-produit","nom":"Présentation produit","parent":"V3-produit-ecommerce"},{"ref":"V3C-produit-ecommerce--univers-de-consommation","slug":"produit-ecommerce--univers-de-consommation","nom":"Univers de consommation","parent":"V3-produit-ecommerce"},{"ref":"V3C-retouche-restauration--compositing-et-decors","slug":"retouche-restauration--compositing-et-decors","nom":"Compositing et décors","parent":"V3-retouche-restauration"},{"ref":"V3C-retouche-restauration--laboratoire-visuel","slug":"retouche-restauration--laboratoire-visuel","nom":"Laboratoire visuel","parent":"V3-retouche-restauration"},{"ref":"V3C-retouche-restauration--liens-et-souvenirs","slug":"retouche-restauration--liens-et-souvenirs","nom":"Liens et souvenirs","parent":"V3-retouche-restauration"},{"ref":"V3C-retouche-restauration--presentation-produit","slug":"retouche-restauration--presentation-produit","nom":"Présentation produit","parent":"V3-retouche-restauration"},{"ref":"V3C-voyages-cultures-epoques--antiquite-et-royaumes","slug":"voyages-cultures-epoques--antiquite-et-royaumes","nom":"Antiquité et royaumes","parent":"V3-voyages-cultures-epoques"},{"ref":"V3C-voyages-cultures-epoques--asies-et-moyen-orient","slug":"voyages-cultures-epoques--asies-et-moyen-orient","nom":"Asies et Moyen-Orient","parent":"V3-voyages-cultures-epoques"},{"ref":"V3C-voyages-cultures-epoques--contemporain-et-futurs","slug":"voyages-cultures-epoques--contemporain-et-futurs","nom":"Contemporain et futurs","parent":"V3-voyages-cultures-epoques"},{"ref":"V3C-voyages-cultures-epoques--destinations-du-monde","slug":"voyages-cultures-epoques--destinations-du-monde","nom":"Destinations du monde","parent":"V3-voyages-cultures-epoques"},{"ref":"V3C-voyages-cultures-epoques--du-moyen-age-au-xixe-siecle","slug":"voyages-cultures-epoques--du-moyen-age-au-xixe-siecle","nom":"Du Moyen Âge au XIXe siècle","parent":"V3-voyages-cultures-epoques"},{"ref":"V3C-voyages-cultures-epoques--europe-ameriques-et-oceanie","slug":"voyages-cultures-epoques--europe-ameriques-et-oceanie","nom":"Europe, Amériques et Océanie","parent":"V3-voyages-cultures-epoques"},{"ref":"V3C-voyages-cultures-epoques--evasion-et-prestige","slug":"voyages-cultures-epoques--evasion-et-prestige","nom":"Évasion et prestige","parent":"V3-voyages-cultures-epoques"},{"ref":"V3C-voyages-cultures-epoques--lieux-et-periodes","slug":"voyages-cultures-epoques--lieux-et-periodes","nom":"Lieux et périodes","parent":"V3-voyages-cultures-epoques"},{"ref":"V3C-voyages-cultures-epoques--nature-et-aventure","slug":"voyages-cultures-epoques--nature-et-aventure","nom":"Nature et aventure","parent":"V3-voyages-cultures-epoques"},{"ref":"V3C-voyages-cultures-epoques--patrimoines-africains","slug":"voyages-cultures-epoques--patrimoines-africains","nom":"Patrimoines africains","parent":"V3-voyages-cultures-epoques"},{"ref":"V3C-voyages-cultures-epoques--photographie-du-xxe-siecle","slug":"voyages-cultures-epoques--photographie-du-xxe-siecle","nom":"Photographie du XXe siècle","parent":"V3-voyages-cultures-epoques"}]$raccourcia$)
as x(ref text, slug text, nom text, parent text);

insert into public.categories (external_ref, slug, name, mode, parent_id, status, is_visible)
select l.ref, l.slug, l.nom, 'image'::public.app_mode, p.id,
       'published'::public.content_status, true
from lot_col_v3 l
join public.categories p on p.external_ref = l.parent
on conflict (external_ref) where external_ref is not null do update
set name = excluded.name,
    parent_id = excluded.parent_id,
    is_visible = true;

do $ctrl$
declare
  v_cat integer;
  v_col integer;
begin
  select count(*) into v_cat from lot_cat_v3 l
  join public.categories c on c.external_ref = l.ref;
  select count(*) into v_col from lot_col_v3 l
  join public.categories c on c.external_ref = l.ref and c.parent_id is not null;

  if v_cat <> 13 then
    raise exception 'Lot 001 : % categories sur 13.', v_cat;
  end if;
  if v_col <> 71 then
    raise exception 'Lot 001 : % collections sur 71.', v_col;
  end if;
  raise notice 'Taxonomie V3 : % categories, % collections.', v_cat, v_col;
end $ctrl$;

drop table lot_cat_v3;
drop table lot_col_v3;

commit;
